import dom,rs
HB='''/// 📽️ Creates a zero-heap placeholder shape that is replaced by its authored variant before any field is copied.
fn empty_shape()->SlideShape{SlideShape::Placeholder{frame:SlideFrame::default(),kind:PlaceholderKind::Title}}
/// 📽️ Fills one optional text field in its original slot from borrowed binary octets.
fn option_into(output:&mut Option<String>,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>Ok(()),1=>{*output=Some(String::new());native::reader_text_into(output.as_mut().unwrap(),reader,control)},_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native optional presence"))}}
/// 📽️ Selects each binary placeholder kind in its retained slot before copying a custom value.
fn placeholder_binary_into(output:&mut PlaceholderKind,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>*output=PlaceholderKind::Title,1=>*output=PlaceholderKind::Subtitle,2=>*output=PlaceholderKind::Body,3=>*output=PlaceholderKind::Footer,4=>*output=PlaceholderKind::SlideNumber,5=>*output=PlaceholderKind::DateTime,6=>{*output=PlaceholderKind::Other{value:String::new()};let PlaceholderKind::Other{value}=&mut *output else{unreachable!()};native::reader_text_into(value,reader,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native placeholder"))}Ok(())}
/// 📽️ Fills a binary block list whose blocks are length-prefixed document text.
fn blocks_binary_into(output:&mut Vec<DocBlock>,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;native::binary_list_into(output,reader,control,limits,entities,Default::default,|block,reader,control,entities|{let body=control.borrow_text(native::bytes(reader)?)?;document_native::block_text_into(block,body,control,limits,entities)})}
/// 📽️ Selects each binary shape variant in its retained slot before copying its text, octets or children.
fn shape_binary_into(output:&mut SlideShape,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;let tag=reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?;let frame=frame_binary(reader)?;match tag{
0=>{*output=SlideShape::TextBox{frame,blocks:Vec::new()};let SlideShape::TextBox{blocks,..}=&mut *output else{unreachable!()};blocks_binary_into(blocks,reader,control,limits,entities)?;},1=>{*output=SlideShape::Picture{frame,image:SlidePictureImage::default()};let SlideShape::Picture{image,..}=&mut *output else{unreachable!()};native::reader_text_into(&mut image.asset_id,reader,control)?;native::reader_text_into(&mut image.mime,reader,control)?;native::reader_bytes_into(&mut image.bytes,reader,control)?;},
2=>{*output=SlideShape::Table{frame,rows:Vec::new()};let SlideShape::Table{rows,..}=&mut *output else{unreachable!()};native::binary_list_into(rows,reader,control,limits,entities,Default::default,|row,reader,control,entities|native::binary_list_into(&mut row.cells,reader,control,limits,entities,Default::default,|cell,reader,control,entities|blocks_binary_into(&mut cell.blocks,reader,control,limits,entities)))?;},3=>{*output=SlideShape::Placeholder{frame,kind:PlaceholderKind::Title};let SlideShape::Placeholder{kind,..}=&mut *output else{unreachable!()};placeholder_binary_into(kind,reader,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native shape"))}Ok(())}
/// 📽️ Fills a binary shape list, inserting each shape before its variant is selected.
fn shapes_binary_into(output:&mut Vec<SlideShape>,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::binary_list_into(output,reader,control,limits,entities,empty_shape,|shape,reader,control,entities|shape_binary_into(shape,reader,control,limits,entities))}
'''
B='''/// 🧩️ Fills the retained presentation root from borrowed binary octets, inserting every master, layout, slide and shape before its fields.
pub fn binary_into(output:&mut SemioPresentationSnapshot,body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Presentation native format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;native::reader_text_into(&mut output.schema,&mut reader,control)?;
 native::binary_list_into(&mut output.masters,&mut reader,control,limits,&mut entities,Default::default,|master,reader,control,entities|{native::reader_text_into(&mut master.id,reader,control)?;shapes_binary_into(&mut master.shapes,reader,control,limits,entities)})?;
 native::binary_list_into(&mut output.layouts,&mut reader,control,limits,&mut entities,Default::default,|layout,reader,control,entities|{native::reader_text_into(&mut layout.id,reader,control)?;native::reader_text_into(&mut layout.master_id,reader,control)?;shapes_binary_into(&mut layout.shapes,reader,control,limits,entities)})?;
 native::binary_list_into(&mut output.slides,&mut reader,control,limits,&mut entities,Default::default,|slide,reader,control,entities|{native::reader_text_into(&mut slide.id,reader,control)?;option_into(&mut slide.layout_id,reader,control)?;shapes_binary_into(&mut slide.shapes,reader,control,limits,entities)?;blocks_binary_into(&mut slide.notes,reader,control,limits,entities)})?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Presentation native trailing bytes"))}Ok(())}
'''
HT='''/// 📽️ Fills one optional hexadecimal text field in its original slot.
fn optional_text_into(output:&mut Option<String>,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if value=="[0]"{return Ok(())}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native optional presence"))}*output=Some(String::new());native::hex_text_into(output.as_mut().unwrap(),value,control)}
/// 📽️ Selects each text placeholder kind in its retained slot before copying a custom value.
fn placeholder_text_into(output:&mut PlaceholderKind,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match value{"T"=>*output=PlaceholderKind::Title,"S"=>*output=PlaceholderKind::Subtitle,"B"=>*output=PlaceholderKind::Body,"F"=>*output=PlaceholderKind::Footer,"N"=>*output=PlaceholderKind::SlideNumber,"D"=>*output=PlaceholderKind::DateTime,_=>{let value=value.strip_prefix('O').ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native placeholder"))?;let[value]=native::record(value,control)?;*output=PlaceholderKind::Other{value:String::new()};let PlaceholderKind::Other{value:slot}=&mut *output else{unreachable!()};native::hex_text_into(slot,value,control)?;}}Ok(())}
/// 📽️ Selects each text shape variant in its retained slot before copying its text, octets or children.
fn shape_text_into(output:&mut SlideShape,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Presentation native shape tag missing"))?;let[frame,value]=native::record(value,control)?;let frame=frame_text(frame,control)?;match tag{
"X"=>{*output=SlideShape::TextBox{frame,blocks:Vec::new()};let SlideShape::TextBox{blocks,..}=&mut *output else{unreachable!()};document_native::blocks_text_into(blocks,value,control,limits,entities)?;},
"P"=>{let[asset_id,mime,bytes]=native::record(value,control)?;*output=SlideShape::Picture{frame,image:SlidePictureImage::default()};let SlideShape::Picture{image,..}=&mut *output else{unreachable!()};native::hex_text_into(&mut image.asset_id,asset_id,control)?;native::hex_text_into(&mut image.mime,mime,control)?;native::hex_bytes_into(&mut image.bytes,bytes,control)?;},
"T"=>{*output=SlideShape::Table{frame,rows:Vec::new()};let SlideShape::Table{rows,..}=&mut *output else{unreachable!()};native::text_list_into(rows,value,control,limits,entities,Default::default,|row,value,control,entities|native::text_list_into(&mut row.cells,value,control,limits,entities,Default::default,|cell,value,control,entities|document_native::blocks_text_into(&mut cell.blocks,value,control,limits,entities)))?;},"H"=>{*output=SlideShape::Placeholder{frame,kind:PlaceholderKind::Title};let SlideShape::Placeholder{kind,..}=&mut *output else{unreachable!()};placeholder_text_into(kind,value,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Presentation native shape"))}Ok(())}
/// 📽️ Fills a text shape list, inserting each shape before its variant is selected.
fn shapes_text_into(output:&mut Vec<SlideShape>,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::text_list_into(output,value,control,limits,entities,empty_shape,|shape,value,control,entities|shape_text_into(shape,value,control,limits,entities))}
'''
D='''/// 📝️ Fills the retained presentation root from the borrowed document body, inserting every master, layout, slide and shape before its fields.
pub fn document_into(output:&mut SemioPresentationSnapshot,body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_document(body,control,limits)?;let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","masters","layouts","slides"],control)?;let schema=fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Presentation native schema missing"))?;let masters=fields[1].unwrap_or("[]");let layouts=fields[2].unwrap_or("[]");let slides=fields[3].unwrap_or("[]");native::hex_text_into(&mut output.schema,schema,control)?;
 native::text_list_into(&mut output.masters,masters,control,limits,&mut entities,Default::default,|master,value,control,entities|{let[id,shapes]=native::record(value,control)?;native::hex_text_into(&mut master.id,id,control)?;shapes_text_into(&mut master.shapes,shapes,control,limits,entities)})?;
 native::text_list_into(&mut output.layouts,layouts,control,limits,&mut entities,Default::default,|layout,value,control,entities|{let[id,master_id,shapes]=native::record(value,control)?;native::hex_text_into(&mut layout.id,id,control)?;native::hex_text_into(&mut layout.master_id,master_id,control)?;shapes_text_into(&mut layout.shapes,shapes,control,limits,entities)})?;
 native::text_list_into(&mut output.slides,slides,control,limits,&mut entities,Default::default,|slide,value,control,entities|{let[id,layout_id,shapes,notes]=native::record(value,control)?;native::hex_text_into(&mut slide.id,id,control)?;optional_text_into(&mut slide.layout_id,layout_id,control)?;shapes_text_into(&mut slide.shapes,shapes,control,limits,entities)?;document_native::blocks_text_into(&mut slide.notes,notes,control,limits,entities)})}
'''
p=rs.native("📽️presentation")
print(dom.apply("📽️presentation",B,D,remove=("option","placeholder_binary","blocks_binary","shape_binary","shapes_binary","optional_text","placeholder_text","shape_text","shapes_text")))
s=open(p,encoding="utf-8").read()
s=s.replace("/// 🧩️ Fills the retained presentation root",HB+"/// 🧩️ Fills the retained presentation root",1)
s=s.replace("/// 📝️ Fills the retained presentation root",HT+"/// 📝️ Fills the retained presentation root",1)
s=s.rstrip("\n")+"\n/// 🕳️ The empty typed root every native prefix starts from.\npub fn empty()->SemioPresentationSnapshot{SemioPresentationSnapshot{schema:String::new(),masters:Vec::new(),layouts:Vec::new(),slides:Vec::new()}}\n"
open(p,"w",encoding="utf-8").write(s)
print(dom.fmt("📽️presentation"))
